(function(){
const $=id=>document.getElementById(id);const missions=[{id:'contact',name:'The belt will not start',lesson:14,cause:'logic',brief:'Start is on, Stop is off, and the transfer is clear. Inspect the ladder and find the contact preventing the motor from running.'},{id:'sensor',name:'Three boxes, one count',lesson:11,cause:'sensor',brief:'Boxes pass the photoeye, but the counter only increments once. Watch the physical beam and the Sensor input. Find why they disagree.'},{id:'feedback',name:'Commanded, but not confirmed',lesson:24,cause:'feedback',brief:'The motor is commanded on, but the alarm comes on after the startup delay. Compare the command and the run feedback.'},{id:'jam',name:'Blocked transfer',lesson:23,cause:'jam',brief:'The jam alarm stays on. Determine whether the program or the simulated physical condition needs attention.'}];let active=null,fault=false,evidence=false,done={};try{done=JSON.parse(localStorage.getItem('plcquest.missions.v1'))||{};}catch{}
const button=document.createElement('button');button.id='modeMissions';button.textContent='Missions';document.querySelector('.modebar').append(button);
const panel=document.createElement('section');panel.id='missionPanel';panel.className='missionpanel';panel.hidden=true;panel.innerHTML=`<span class="eyebrow">TROUBLESHOOTING BENCH</span><div class="workshopbar"><select id="missionSelect" aria-label="Troubleshooting mission"></select><button id="missionStart" class="quiet">Start mission</button></div><p id="missionBrief"></p><details><summary>Physical repair options</summary><p>Watch the inputs and outputs before choosing a repair. Ladder errors must be corrected in the ladder editor below.</p><div class="workshopbar"><select id="missionCause" aria-label="Diagnosis"><option value="sensor">Sensor input stuck on</option><option value="feedback">Missing run feedback</option><option value="jam">Physical obstruction</option><option value="logic">Incorrect ladder contact</option></select><button id="missionRepair" class="quiet">Apply repair</button></div></details><p id="missionMessage" role="status"></p>`;document.querySelector('.brief').before(panel);
function list(){$('missionSelect').innerHTML=missions.map((m,i)=>`<option value="${i}">${done[m.id]?'✓ ':''}${m.name}</option>`).join('');}
function start(i=0){active=missions[i]||missions[0];fault=active.cause!=='logic';evidence=false;showMode('missions');const l=LESSONS[active.lesson];load(active.lesson,{...l,title:active.name,goal:active.brief,initial:active.cause==='logic'?{...l.initial}:{...l.answer}});inputs.START=true;if(active.cause==='jam')inputs.BLOCKED=true;update();$('missionBrief').textContent=active.brief;$('missionMessage').textContent='Run the simulator, inspect the inputs, then verify the repaired system with Test my logic.';}
function prepare(){if(!active||$('missionPanel').hidden)return;if(active.cause==='sensor'&&fault)inputs.SENSOR=true;if(active.cause==='feedback')inputs.FEEDBACK=fault?false:!!state.bits.MOTOR;if(active.cause==='jam')inputs.BLOCKED=fault;}
function observe(){if(!active||$('missionPanel').hidden)return;if(active.cause==='sensor'&&fault&&state.scans>=15)evidence=true;if(['feedback','jam'].includes(active.cause)&&state.bits.LAMP)evidence=true;if(active.cause==='logic'&&state.scans>=2)evidence=true;}
function gate(){if(!active||$('missionPanel').hidden)return null;if(fault)return 'The physical fault is still present. Inspect the live inputs and apply the matching repair.';if(!evidence)return 'Run and observe the original problem before verifying the repair.';if(active.cause==='sensor'&&state.count<3)return 'Run the repaired sensor until three actual boxes have been counted.';if(active.cause==='feedback'&&(!state.bits.MOTOR||!inputs.FEEDBACK||state.bits.LAMP))return 'Run again after repair. Motor and Feedback should be on, with the alarm off.';if(active.cause==='jam'&&(inputs.BLOCKED||state.bits.LAMP||state.scans<1))return 'Scan after clearing the obstruction. Blocked and Lamp should both be off.';return null;}
function passed(){if(active&&!$('missionPanel').hidden){done[active.id]=true;try{localStorage.setItem('plcquest.missions.v1',JSON.stringify(done));}catch{}$('missionMessage').textContent='Mission complete. The repaired program and the observed system behavior both passed.';list();}}
$('missionRepair').onclick=()=>{if(!active)return;const cause=$('missionCause').value;if(cause!==active.cause){$('missionMessage').textContent='That repair did not resolve this fault. Compare the command, input states, and physical behavior.';return;}if(cause==='logic'){$('missionMessage').textContent='Correct the faulty contact in the ladder, then run and test it.';return;}if(!evidence){$('missionMessage').textContent='Run the simulator long enough to observe the symptom first.';return;}fault=false;pause();partialScan=null;state=PLC.fresh();plant=Conveyor.fresh();$('missionMessage').textContent='Physical repair applied. Run again and verify the system.';update();};$('missionStart').onclick=()=>start(Number($('missionSelect').value));button.onclick=()=>start(Number($('missionSelect').value)||0);
window.Missions={start,prepare,observe,gate,passed};list();
})();
